import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Mutue posizioni fra due circonferenze","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/f_geometria-del-piano-euclideo/fj/fje.md","filePath":"lezioni/f_geometria-del-piano-euclideo/fj/fje.md"}`),a={name:`lezioni/f_geometria-del-piano-euclideo/fj/fje.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="mutue-posizioni-fra-due-circonferenze" tabindex="-1">Mutue posizioni fra due circonferenze <a class="header-anchor" href="#mutue-posizioni-fra-due-circonferenze" aria-label="Permalink to “Mutue posizioni fra due circonferenze”">​</a></h1><p>Vediamo ora quali sono le possibili posizioni di due circonferenze caratterizzandole con la distanza fra i centri ed i raggi.</p><blockquote><p><strong>Nota:</strong> Per capire bene procurati due monete di diametro diverso, ad esempio una moneta da 10 centesimi ed una da 50 e prova a vedere, avvicinandole, quante posizioni diverse si possono avere.</p></blockquote><p>Abbiamo sei possibilità.</p><h2 id="_1-circonferenze-esterne" tabindex="-1">1. Circonferenze esterne <a class="header-anchor" href="#_1-circonferenze-esterne" aria-label="Permalink to “1. Circonferenze esterne”">​</a></h2><p>[$$ \\overline{O_1 O_2} &gt; r_1 + r_2 \\quad d &gt; r_1 + r_2</p><p class="katex-block"><span class="katex-error" title="ParseError: KaTeX parse error: Can&#39;t use function &#39;$&#39; in math mode at position 70: …se la distanza $̲d$ fra i due ce…" style="color:#cc0000;">]{.text-blue} Le circonferenze sono fra loro esterne se la distanza $d$ fra i due centri è superiore al valore della somma dei due raggi. Viceversa: se la distanza fra i due centri è superiore al valore della somma dei due raggi allora le circonferenze sono esterne fra loro. ## 2. Circonferenze tangenti esternamente [ </span></p><p>\\overline{O_1 O_2} = r_1 + r_2 \\quad d = r_1 + r_2</p><p class="katex-block"><span class="katex-error" title="ParseError: KaTeX parse error: Can&#39;t use function &#39;$&#39; in math mode at position 84: …se la distanza $̲d$ fra i due ce…" style="color:#cc0000;">]{.text-blue} Le circonferenze sono fra loro tangenti esternamente se la distanza $d$ fra i due centri è uguale al valore della somma dei due raggi. Viceversa: se la distanza fra i due centri è uguale al valore della somma dei due raggi allora le circonferenze sono tangenti esternamente fra loro. ## 3. Circonferenze secanti [ </span></p><p>r_1 + r_2 &gt; \\overline{O_1 O_2} &gt; r_1 - r_2 \\quad d &lt; r_1 + r_2</p><p class="katex-block"><span class="katex-error" title="ParseError: KaTeX parse error: Can&#39;t use function &#39;$&#39; in math mode at position 70: …se la distanza $̲d$ fra i due ce…" style="color:#cc0000;">]{.text-blue} Le circonferenze sono fra loro secanti se la distanza $d$ fra i due centri è inferiore al valore della somma dei due raggi e superiore alla loro differenza. Viceversa: se la distanza fra i due centri è inferiore al valore della somma dei due raggi e superiore alla loro differenza allora le circonferenze sono fra loro secanti. &gt; **Osservazione:** Deriva dalla proprietà dei triangoli per cui un lato $\\overline{O_1 O_2}$ è minore della somma degli altri due lati $PO_1 + PO_2$ ed è anche maggiore della loro differenza $PO_1 - PO_2$. ## 4. Circonferenze tangenti internamente [ </span></p><p>\\overline{O_1 O_2} = r_1 - r_2 \\quad d = r_1 - r_2</p><p class="katex-block"><span class="katex-error" title="ParseError: KaTeX parse error: Can&#39;t use function &#39;$&#39; in math mode at position 84: …se la distanza $̲d$ fra i due ce…" style="color:#cc0000;">]{.text-blue} Le circonferenze sono fra loro tangenti internamente se la distanza $d$ fra i due centri è uguale al valore della differenza dei due raggi. Viceversa: se la distanza fra i due centri è uguale al valore della differenza dei due raggi allora le circonferenze sono fra loro tangenti internamente. ## 5. Circonferenza interna [ </span></p><p>r_1 - r_2 &gt; \\overline{O_1 O_2} &gt; 0 \\quad r_1 - r_2 &gt; d &gt; 0</p><p class="katex-block"><span class="katex-error" title="ParseError: KaTeX parse error: Can&#39;t use function &#39;$&#39; in math mode at position 78: …se la distanza $̲d$ fra i due ce…" style="color:#cc0000;">]{.text-blue} Una circonferenza è interna rispetto all&#39;altra se la distanza $d$ fra i due centri è inferiore al valore della differenza dei due raggi ma è maggiore di zero. Viceversa: se la distanza fra i due centri è inferiore al valore della differenza dei due raggi ed è maggiore di zero allora una circonferenza è interna rispetto all&#39;altra. ## 6. Circonferenze concentriche [ </span></p><p>\\overline{O_1 O_2} = 0 \\quad d = 0</p><p class="katex-block"><span class="katex-error" title="ParseError: KaTeX parse error: Can&#39;t use function &#39;$&#39; in math mode at position 66: …se la distanza $̲d$ fra i due ce…" style="color:#cc0000;">]{.text-blue} Le circonferenze sono concentriche se la distanza $d$ fra i due centri è uguale a zero. Viceversa: se la distanza $d$ fra i due centri è uguale a zero allora le circonferenze sono concentriche.</span></p>`,17)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};